const std = @import("std");

const Queue = struct {
    data: [5]i32 = undefined,
    front: usize = 0,
    rear: usize = 0,
    count: usize = 0,

    fn enqueue(self: *Queue, val: i32) bool {
        if (self.count == self.data.len) return false;
        self.data[self.rear] = val;
        self.rear = (self.rear + 1) % self.data.len;
        self.count += 1;
        return true;
    }

    fn dequeue(self: *Queue) ?i32 {
        if (self.count == 0) return null;
        const val = self.data[self.front];
        self.front = (self.front + 1) % self.data.len;
        self.count -= 1;
        return val;
    }
};

pub fn main() !void {
    var q = Queue{};
    _ = q.enqueue(10);
    _ = q.enqueue(20);
    _ = q.enqueue(30);
    while (q.dequeue()) |val| {
        std.debug.print("{} ", .{val});
    }
    std.debug.print("\n", .{});
}
